import math
from collections import defaultdict

def find_cubic_taxicab(limit):
    sum_to_pairs = defaultdict(list)
    # generate all sums
    for a in range(1, limit+1):
        a3 = a**3
        for b in range(a+1, limit+1):
            s = a3 + b**3
            sum_to_pairs[s].append((a, b))
    # filter sums with at least two representations
    candidates = []
    for s, pairs in sum_to_pairs.items():
        if len(pairs) >= 2:
            # check if s is a perfect cube
            k = round(s ** (1/3))
            if k**3 == s:
                candidates.append((s, k, pairs))
    return candidates

if __name__ == "__main__":
    max_n = 2000  # increase if needed
    print(f"Searching up to {max_n}...")
    cand = find_cubic_taxicab(max_n)
    if cand:
        cand.sort(key=lambda x: x[0])
        for s, k, pairs in cand:
            print(f"Cube {s} = {k}^3")
            for a,b in pairs:
                print(f"  {a}^3 + {b}^3")
    else:
        print("No candidates found.")

import math
from collections import defaultdict

def is_perfect_cube(n):
    # integer cube root
    k = round(n ** (1/3))
    return k**3 == n

def find_cube(limit):
    sum_to_pairs = defaultdict(list)
    # generate sums
    for a in range(1, limit+1):
        a3 = a**3
        for b in range(a+1, limit+1):
            s = a3 + b**3
            sum_to_pairs[s].append((a, b))
    # filter
    candidates = []
    for s, pairs in sum_to_pairs.items():
        if len(pairs) >= 2 and is_perfect_cube(s):
            candidates.append((s, pairs))
    return candidates

if __name__ == "__main__":
    for limit in [5000, 10000, 15000]:
        print(f"Searching up to {limit}...")
        cand = find_cube(limit)
        if cand:
            cand.sort(key=lambda x: x[0])
            for s, pairs in cand:
                k = round(s ** (1/3))
                print(f"Cube {s} = {k}^3")
                for a,b in pairs:
                    print(f"  {a}^3 + {b}^3")
            break
    else:
        print("No candidates found up to 15000.")

