import math

def find_cube(limit_k):
    for k in range(1, limit_k+1):
        k3 = k**3
        reps = []
        for a in range(1, k):
            a3 = a**3
            rem = k3 - a3
            if rem <= 0:
                break
            # compute integer cube root of rem
            b = round(rem ** (1/3))
            if b**3 == rem and b > a:
                reps.append((a, b))
            elif (b-1)**3 == rem and b-1 > a:
                reps.append((a, b-1))
            elif (b+1)**3 == rem and b+1 > a:
                reps.append((a, b+1))
        if len(reps) >= 2:
            print(f"Cube {k3} = {k}^3")
            for a,b in reps:
                print(f"  {a}^3 + {b}^3")
            return k, reps
    return None

if __name__ == "__main__":
    res = find_cube(2000)
    if res is None:
        print("No cube found up to k=2000.")
